#!/usr/bin/env bash
set -Eeuo pipefail

UPDATE_NAME="Update 004 - Complete Customization Configuration"
DB_NAME="dnsapproval"
VERSION_FILE="/var/lib/portal/update-version"
APPEARANCE_DIR="/opt/portal/web/uploads/appearance"
BACKUP_ROOT="/var/backups/portal"
STAGE_DIR=""
BACKUP_DIR=""
DB_BACKUP_SCHEMA="update004_backup_$$"
BACKUP_SCHEMA_READY=0
ASSET_INSTALL_STARTED=0
ORIGINAL_ASSET_DIR_PRESENT=0

log() { printf '\n======================================================================\n%s\n======================================================================\n' "$1"; }
ok() { echo "[ OK ] $1"; }
warn() { echo "[WARN] $1"; }
fail() { echo "[ERROR] $1" >&2; return 1; }

rollback_update() {
    local rc="${1:-1}"
    trap - ERR EXIT

    warn "Update 004 failed; starting rollback"

    if [[ "$BACKUP_SCHEMA_READY" -eq 1 ]]; then
        sudo -u postgres psql -v ON_ERROR_STOP=1 -d "$DB_NAME" >/dev/null <<SQL || true
BEGIN;
DELETE FROM public.group_permissions;
DELETE FROM public.user_custom_field_values;
DELETE FROM public.user_custom_fields;
DELETE FROM public.user_custom_field_sections;
DELETE FROM public.permissions;
DELETE FROM public.portal_settings;

INSERT INTO public.permissions SELECT * FROM ${DB_BACKUP_SCHEMA}.permissions;
INSERT INTO public.group_permissions SELECT * FROM ${DB_BACKUP_SCHEMA}.group_permissions;
INSERT INTO public.portal_settings SELECT * FROM ${DB_BACKUP_SCHEMA}.portal_settings;
INSERT INTO public.user_custom_field_sections SELECT * FROM ${DB_BACKUP_SCHEMA}.user_custom_field_sections;
INSERT INTO public.user_custom_fields SELECT * FROM ${DB_BACKUP_SCHEMA}.user_custom_fields;
INSERT INTO public.user_custom_field_values SELECT * FROM ${DB_BACKUP_SCHEMA}.user_custom_field_values;

SELECT setval(pg_get_serial_sequence('public.permissions','id'),
              COALESCE((SELECT MAX(id) FROM public.permissions), 1),
              EXISTS (SELECT 1 FROM public.permissions));
SELECT setval(pg_get_serial_sequence('public.user_custom_field_sections','id'),
              COALESCE((SELECT MAX(id) FROM public.user_custom_field_sections), 1),
              EXISTS (SELECT 1 FROM public.user_custom_field_sections));
SELECT setval(pg_get_serial_sequence('public.user_custom_fields','id'),
              COALESCE((SELECT MAX(id) FROM public.user_custom_fields), 1),
              EXISTS (SELECT 1 FROM public.user_custom_fields));
COMMIT;
DROP SCHEMA IF EXISTS ${DB_BACKUP_SCHEMA} CASCADE;
SQL
        warn "Database configuration restored"
    fi

    if [[ "$ASSET_INSTALL_STARTED" -eq 1 && -n "$BACKUP_DIR" ]]; then
        rm -rf -- "$APPEARANCE_DIR"
        if [[ "$ORIGINAL_ASSET_DIR_PRESENT" -eq 1 ]]; then
            tar -xzf "$BACKUP_DIR/appearance-before.tar.gz" -C /
        fi
        warn "Appearance assets restored"
    fi

    if [[ -n "$BACKUP_DIR" && -f "$BACKUP_DIR/update-version" ]]; then
        cp -a "$BACKUP_DIR/update-version" "$VERSION_FILE"
    fi

    systemctl restart portal-api.service >/dev/null 2>&1 || true
    [[ -z "$STAGE_DIR" || ! -d "$STAGE_DIR" ]] || rm -rf -- "$STAGE_DIR"
    exit "$rc"
}

trap 'rollback_update $?' ERR

log "$UPDATE_NAME"

[[ $EUID -eq 0 ]] || fail "This update must run as root"
[[ -f "$VERSION_FILE" ]] || fail "Update version file not found"
[[ "$(tr -d '[:space:]' < "$VERSION_FILE")" == "3" ]] \
    || fail "Update 004 requires installed update level 3"

for cmd in base64 curl find pg_dump pg_restore psql sha256sum systemctl tar; do
    command -v "$cmd" >/dev/null 2>&1 || fail "Required command not found: $cmd"
done

for table in permissions group_permissions groups portal_settings \
             user_custom_field_sections user_custom_fields user_custom_field_values; do
    [[ "$(sudo -u postgres psql -d "$DB_NAME" -Atqc \
        "SELECT to_regclass('public.${table}') IS NOT NULL;")" == "t" ]] \
        || fail "Required database table missing: $table"
done

[[ "$(sudo -u postgres psql -d "$DB_NAME" -Atqc \
    "SELECT COUNT(*) FROM groups WHERE LOWER(group_name)=LOWER('Administrators');")" == "1" ]] \
    || fail "Exactly one Administrators group is required"

for permission_key in appearance security customization edit_user_fields \
                      theme sidebar user_disclaimer; do
    permission_count="$(sudo -u postgres psql -d "$DB_NAME" -Atqc \
        "SELECT COUNT(*) FROM permissions WHERE permission_key='${permission_key}';")"
    [[ "$permission_count" -le 1 ]] \
        || fail "Duplicate permission key detected: $permission_key"
done

[[ "$(sudo -u postgres psql -d "$DB_NAME" -Atqc \
    "SELECT COUNT(*) FROM permissions WHERE permission_key IN ('appearance','security');")" == "2" ]] \
    || fail "Required Appearance or Security permission is missing"

STAGE_DIR="$(mktemp -d /tmp/portal-update-004.XXXXXX)"
chmod 755 "$STAGE_DIR"

cat > "$STAGE_DIR/portal-settings.csv.b64" <<'UPDATE004_SETTINGS_B64'
