P//P/wHwiFFAAHAIAA==
UPDATE004_ASSETS_B64

base64 -d "$STAGE_DIR/portal-settings.csv.b64" > "$STAGE_DIR/portal-settings.csv"
base64 -d "$STAGE_DIR/appearance-assets.tar.gz.b64" > "$STAGE_DIR/appearance-assets.tar.gz"
chmod 644 "$STAGE_DIR/portal-settings.csv" "$STAGE_DIR/appearance-assets.tar.gz"

[[ "$(sha256sum "$STAGE_DIR/portal-settings.csv" | awk '{print $1}')" == \
   "da0fdc5284e5b89bf9eab6ebf13260cb70986421edde3091f88ffed5406015e3" ]] \
    || fail "Portal settings payload checksum mismatch"
[[ "$(sha256sum "$STAGE_DIR/appearance-assets.tar.gz" | awk '{print $1}')" == \
   "ea2941afded7692c54585bffe9ea0c025358ecea4d427f65de04619a266c8c61" ]] \
    || fail "Appearance asset payload checksum mismatch"

tar -tzf "$STAGE_DIR/appearance-assets.tar.gz" > "$STAGE_DIR/assets.list"
[[ "$(grep -c '\.webp$' "$STAGE_DIR/assets.list")" == "3" ]] \
    || fail "Appearance payload must contain exactly three WebP assets"

tar -xzf "$STAGE_DIR/appearance-assets.tar.gz" -C "$STAGE_DIR"

sha256sum "$STAGE_DIR/opt/portal/web/uploads/appearance/"*.webp \
    > "$STAGE_DIR/appearance-assets.sha256"

log "BACKING UP CLIENT CONFIGURATION"

BACKUP_DIR="$BACKUP_ROOT/update-004-$(date +%Y%m%d-%H%M%S)"
mkdir -p "$BACKUP_DIR"

sudo -u postgres pg_dump --format=custom "$DB_NAME" > "$BACKUP_DIR/dnsapproval.dump"
chmod 600 "$BACKUP_DIR/dnsapproval.dump"
pg_restore --list "$BACKUP_DIR/dnsapproval.dump" >/dev/null
cp -a "$VERSION_FILE" "$BACKUP_DIR/update-version"

if [[ -d "$APPEARANCE_DIR" ]]; then
    ORIGINAL_ASSET_DIR_PRESENT=1
    tar -czf "$BACKUP_DIR/appearance-before.tar.gz" -C / \
        opt/portal/web/uploads/appearance
fi

sha256sum "$BACKUP_DIR/dnsapproval.dump" "$BACKUP_DIR/update-version" \
    > "$BACKUP_DIR/SHA256SUMS"
[[ "$ORIGINAL_ASSET_DIR_PRESENT" -eq 0 ]] || \
    sha256sum "$BACKUP_DIR/appearance-before.tar.gz" >> "$BACKUP_DIR/SHA256SUMS"
ok "Validated backup created: $BACKUP_DIR"

log "SNAPSHOTTING CONFIGURATION FOR AUTOMATIC ROLLBACK"

sudo -u postgres psql -v ON_ERROR_STOP=1 -d "$DB_NAME" >/dev/null <<SQL
CREATE SCHEMA ${DB_BACKUP_SCHEMA};
CREATE TABLE ${DB_BACKUP_SCHEMA}.permissions AS TABLE public.permissions;
CREATE TABLE ${DB_BACKUP_SCHEMA}.group_permissions AS TABLE public.group_permissions;
CREATE TABLE ${DB_BACKUP_SCHEMA}.portal_settings AS TABLE public.portal_settings;
CREATE TABLE ${DB_BACKUP_SCHEMA}.user_custom_field_sections AS TABLE public.user_custom_field_sections;
CREATE TABLE ${DB_BACKUP_SCHEMA}.user_custom_fields AS TABLE public.user_custom_fields;
CREATE TABLE ${DB_BACKUP_SCHEMA}.user_custom_field_values AS TABLE public.user_custom_field_values;
SQL
BACKUP_SCHEMA_READY=1
ok "Rollback snapshot created"

log "INSTALLING VERIFIED APPEARANCE ASSETS"

ASSET_INSTALL_STARTED=1
install -d -m 775 "$APPEARANCE_DIR"
cp -a "$STAGE_DIR/opt/portal/web/uploads/appearance/." "$APPEARANCE_DIR/"
if id www-data >/dev/null 2>&1; then
    chown -R www-data:www-data "$APPEARANCE_DIR"
fi

[[ "$(sha256sum "$APPEARANCE_DIR/logo_75692baaae5fd877a69b5707cefe6f94.webp" | awk '{print $1}')" == \
   "$(sha256sum "$STAGE_DIR/opt/portal/web/uploads/appearance/logo_75692baaae5fd877a69b5707cefe6f94.webp" | awk '{print $1}')" ]]
[[ "$(sha256sum "$APPEARANCE_DIR/login_277c04f208af649b7615e6d3bcfdffa5.webp" | awk '{print $1}')" == \
   "$(sha256sum "$STAGE_DIR/opt/portal/web/uploads/appearance/login_277c04f208af649b7615e6d3bcfdffa5.webp" | awk '{print $1}')" ]]
[[ "$(sha256sum "$APPEARANCE_DIR/banner_e3e8fc3408713fe3163376d80e6ffcea.webp" | awk '{print $1}')" == \
   "$(sha256sum "$STAGE_DIR/opt/portal/web/uploads/appearance/banner_e3e8fc3408713fe3163376d80e6ffcea.webp" | awk '{print $1}')" ]]
ok "All three appearance assets installed and verified"

log "MIGRATING PERMISSIONS, SETTINGS AND CUSTOM FIELDS"

sudo -u postgres psql -v ON_ERROR_STOP=1 -d "$DB_NAME" <<SQL
BEGIN;

CREATE TEMP TABLE update004_settings (
    setting_key VARCHAR(100),
    setting_value TEXT,
    updated_at TIMESTAMP WITHOUT TIME ZONE
);
\copy update004_settings FROM '$STAGE_DIR/portal-settings.csv' WITH (FORMAT csv, HEADER true)

INSERT INTO portal_settings (setting_key, setting_value, updated_at)
SELECT setting_key, setting_value, updated_at
FROM update004_settings
ON CONFLICT (setting_key) DO UPDATE
SET setting_value = EXCLUDED.setting_value,
    updated_at = EXCLUDED.updated_at;

INSERT INTO permissions (permission_key, permission_name, parent_id)
SELECT 'customization', 'Customization', NULL
WHERE NOT EXISTS (SELECT 1 FROM permissions WHERE permission_key='customization');

INSERT INTO permissions (permission_key, permission_name, parent_id)
SELECT 'edit_user_fields', 'Edit User Fields', id
FROM permissions WHERE permission_key='security'
AND NOT EXISTS (SELECT 1 FROM permissions WHERE permission_key='edit_user_fields');

INSERT INTO permissions (permission_key, permission_name, parent_id)
SELECT item.permission_key, item.permission_name, appearance.id
FROM (VALUES
    ('theme', 'Theme'),
    ('sidebar', 'Sidebar'),
    ('user_disclaimer', 'User Disclaimer')
) AS item(permission_key, permission_name)
CROSS JOIN permissions appearance
WHERE appearance.permission_key='appearance'
  AND NOT EXISTS (
      SELECT 1 FROM permissions p WHERE p.permission_key=item.permission_key
  );

UPDATE permissions
SET permission_name='Customization', parent_id=NULL
WHERE permission_key='customization';

UPDATE permissions
SET permission_name='Appearance',
    parent_id=(SELECT id FROM permissions WHERE permission_key='customization')
WHERE permission_key='appearance';

UPDATE permissions
SET permission_name='Edit User Fields',
    parent_id=(SELECT id FROM permissions WHERE permission_key='security')
WHERE permission_key='edit_user_fields';

UPDATE permissions
SET permission_name=CASE permission_key
        WHEN 'theme' THEN 'Theme'
        WHEN 'sidebar' THEN 'Sidebar'
        WHEN 'user_disclaimer' THEN 'User Disclaimer'
    END,
    parent_id=(SELECT id FROM permissions WHERE permission_key='appearance')
WHERE permission_key IN ('theme','sidebar','user_disclaimer');

INSERT INTO group_permissions (group_id, permission_id)
SELECT g.id, p.id
FROM groups g
CROSS JOIN permissions p
WHERE LOWER(g.group_name)=LOWER('Administrators')
  AND p.permission_key IN (
      'customization','appearance','edit_user_fields','theme','sidebar','user_disclaimer'
  )
  AND NOT EXISTS (
      SELECT 1 FROM group_permissions gp
      WHERE gp.group_id=g.id AND gp.permission_id=p.id
  );

DELETE FROM group_permissions
WHERE permission_id IN (
    SELECT id FROM permissions
    WHERE permission_key IN ('portal_name','background','button_colours')
);
DELETE FROM permissions
WHERE permission_key IN ('portal_name','background','button_colours');

INSERT INTO user_custom_field_sections (section_name, sort_order)
SELECT 'Custom User Fields', 10
WHERE NOT EXISTS (
    SELECT 1 FROM user_custom_field_sections
    WHERE LOWER(section_name)=LOWER('Custom User Fields')
);

INSERT INTO user_custom_fields
    (field_name, field_key, field_type, required, sort_order, section_id, prepend, append)
SELECT 'Employee Number','employee_number','text',FALSE,10,s.id,'EMP-',''
FROM user_custom_field_sections s
WHERE LOWER(s.section_name)=LOWER('Custom User Fields')
  AND NOT EXISTS (
      SELECT 1 FROM user_custom_fields
      WHERE LOWER(field_key)=LOWER('employee_number')
  );

SELECT setval(pg_get_serial_sequence('public.permissions','id'),
              COALESCE((SELECT MAX(id) FROM permissions),1),
              EXISTS (SELECT 1 FROM permissions));
COMMIT;
SQL

ok "Configuration database migration completed"

log "RESTARTING AND VALIDATING PORTAL"

systemctl restart portal-api.service
HTTP_STATUS="000"
for attempt in $(seq 1 30); do
    HTTP_STATUS="$(curl -sS -o "$STAGE_DIR/stats.json" -w '%{http_code}' \
        http://127.0.0.1:8000/stats 2>/dev/null || true)"
    [[ "$HTTP_STATUS" == "200" ]] && break
    sleep 1
done
[[ "$HTTP_STATUS" == "200" ]] \
    || fail "Portal API health check failed after 30 attempts with HTTP $HTTP_STATUS"

SETTINGS_MISMATCH="$({ sudo -u postgres psql -qAt -v ON_ERROR_STOP=1 -d "$DB_NAME" <<SQL
CREATE TEMP TABLE expected_settings (
    setting_key VARCHAR(100), setting_value TEXT,
    updated_at TIMESTAMP WITHOUT TIME ZONE
);
\copy expected_settings FROM '$STAGE_DIR/portal-settings.csv' WITH (FORMAT csv, HEADER true)
SELECT COUNT(*) FROM (
    (SELECT setting_key, setting_value FROM expected_settings
     EXCEPT SELECT setting_key, setting_value FROM portal_settings)
    UNION ALL
    (SELECT setting_key, setting_value FROM portal_settings
     WHERE setting_key IN (SELECT setting_key FROM expected_settings)
     EXCEPT SELECT setting_key, setting_value FROM expected_settings)
) differences;
SQL
} | tail -n 1)"
[[ "$SETTINGS_MISMATCH" == "0" ]] || fail "Portal setting parity validation failed"

PERMISSION_MATCHES="$(sudo -u postgres psql -d "$DB_NAME" -Atqc "
SELECT COUNT(*)
FROM permissions child
LEFT JOIN permissions parent ON parent.id=child.parent_id
WHERE (child.permission_key='customization' AND child.permission_name='Customization'
       AND child.parent_id IS NULL)
   OR (child.permission_key='appearance' AND child.permission_name='Appearance'
       AND parent.permission_key='customization')
   OR (child.permission_key='edit_user_fields' AND child.permission_name='Edit User Fields'
       AND parent.permission_key='security')
   OR (child.permission_key='theme' AND child.permission_name='Theme'
       AND parent.permission_key='appearance')
   OR (child.permission_key='sidebar' AND child.permission_name='Sidebar'
       AND parent.permission_key='appearance')
   OR (child.permission_key='user_disclaimer' AND child.permission_name='User Disclaimer'
       AND parent.permission_key='appearance');")"
[[ "$PERMISSION_MATCHES" == "6" ]] || fail "Permission hierarchy validation failed"

ADMIN_PERMISSION_MATCHES="$(sudo -u postgres psql -d "$DB_NAME" -Atqc "
SELECT COUNT(*) FROM group_permissions gp
JOIN groups g ON g.id=gp.group_id
JOIN permissions p ON p.id=gp.permission_id
WHERE LOWER(g.group_name)=LOWER('Administrators')
AND p.permission_key IN
('customization','appearance','edit_user_fields','theme','sidebar','user_disclaimer');")"
[[ "$ADMIN_PERMISSION_MATCHES" == "6" ]] || fail "Administrator permission validation failed"

[[ "$(sudo -u postgres psql -d "$DB_NAME" -Atqc \
    "SELECT COUNT(*) FROM permissions WHERE permission_key IN ('portal_name','background','button_colours');")" == "0" ]] \
    || fail "Obsolete permission cleanup validation failed"

[[ "$(sudo -u postgres psql -d "$DB_NAME" -Atqc \
    "SELECT COUNT(*) FROM user_custom_fields WHERE LOWER(field_key)=LOWER('employee_number');")" == "1" ]] \
    || fail "Employee Number custom field validation failed"

sudo -u postgres psql -v ON_ERROR_STOP=1 -d "$DB_NAME" \
    -c "DROP SCHEMA IF EXISTS ${DB_BACKUP_SCHEMA} CASCADE;" >/dev/null
BACKUP_SCHEMA_READY=0
ASSET_INSTALL_STARTED=0

echo 4 > "$VERSION_FILE"
chmod 644 "$VERSION_FILE"

rm -rf -- "$STAGE_DIR"
STAGE_DIR=""
trap - ERR

log "UPDATE 004 COMPLETE"
ok "Customization permissions match the Dev hierarchy"
ok "All 96 Dev portal settings verified"
ok "All three Dev appearance assets verified"
ok "Employee Number custom field verified"
ok "Portal API health check returned HTTP 200"
ok "Installed update level is now 4"
